void Effect_KartWaveGlow_Update(WaveGlowEffect *effect) {
    float matrix[16];
    switch (effect->state) {
    case 0:
        if (effect->kart == 0) {
            DrawEffect_Free(effect);
            return;
        }
        VfxSlot_BindResourceEx(effect->slot, 0x64, 0);
        VfxSlot_SetAnimSpeed(effect->slot, lbl_806D540C);
        effect->scale = lbl_806D5424;
        VfxSlot_SetScaleUniform(effect->slot, effect->scale);
        ++effect->state;
        break;
    case 1:
        break;
    }
    if (effect->finished == 1) {
        DrawEffect_Free(effect);
        return;
    }
    Mtx_TransposeToMtx44(matrix, KartDriver_GetKartRootMtx(effect->kart));
    Mtx44_TransformVec3(&effect->position, matrix, Effect_KartWaveGlow_Update_rodata_8032A748);
    VfxSlot_SetPositionFromVec(effect->slot, effect->position);
    if (FinalLapCoinJump_CheckActiveForObject(effect->kart)) effect->visible = 0;
    else effect->visible = 1;
}
